      "@id": "https://www.emuqi.com/blog/solid-hydrogen-procurement-decision-tree-en.html#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "When should a brand choose solid-state hydrogen media over PEM electrolysis?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Choose solid-state media when the SKU has no reliable power path, needs 18–24 hour hydrogen half-life after preparation, targets consumable refill revenue, or must enter wet-room, travel, bath, sachet, soap, or agriculture formats. Choose PEM when you are building a countertop or inhalation device with continuous power and instant peak concentration while running."
          }
        },
        {
          "@type": "Question",
          "name": "What belongs in an RFP for solid-state hydrogen materials?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Require dissolved-hydrogen ppb at a stated water volume and contact time, half-life under sealed storage, ORP, particle size and dosage per liter, batch COA, third-party reports (SGS or equivalent), heavy metals and microbial limits, OEM customization range, MOQ and sample lead time (typical MUQI sample window 5–22 days), and stability under your product's pH and temperature."
          }
        },
        {
          "@type": "Question",
          "name": "How do total cost of ownership differ between media and PEM devices?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "PEM devices concentrate cost in BOM, battery, electronics certification, and warranty; media concentrate cost in per-unit consumable and packaging. For multi-SKU portfolios that include bottles, filters, tablets, or bath products, media often produce higher lifetime gross profit through refills even when unit COGS differ. Model three-year refill attach rate before locking hardware-only economics."
          }
        },
        {
          "@type": "Question",
          "name": "Can solid-state and PEM technologies be used together in one product line?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Many brands run PEM for home countertop or inhalation products and solid-state media for portable bottles, purifier cartridges, tablets, soap, foot bath, and travel formats. The procurement decision tree treats them as complementary tools: allocate by use-case, power availability, and revenue model rather than forcing a single winner."
          }
        }
      ]
    }
